begin;
create extension if not exists pgtap with schema extensions;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99992000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Source integrity course','Synthetic','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','99992100-0000-4000-8000-000000000001','99992000-0000-4000-8000-000000000001','Source unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','99992200-0000-4000-8000-000000000001','99992100-0000-4000-8000-000000000001','Source lesson',1,'School content');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)select'10000000-0000-4000-8000-000000000001',('99992300-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'99992200-0000-4000-8000-000000000001','Practice '||n,'practice','School task',n from generate_series(1,2)n;
insert into app.activity_completions(school_id,id,activity_id,learner_id,completed_at)select'10000000-0000-4000-8000-000000000001',('99992400-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('99992300-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000012','2026-10-01T10:00:00Z'from generate_series(1,2)n;
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,completed_at)select'10000000-0000-4000-8000-000000000001',('99992500-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=1 then'20000000-0000-4000-8000-000000000012'::uuid else'20000000-0000-4000-8000-000000000013'::uuid end,'activity.complete','activity',('99992400-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,1,'{}','observation-source-integrity-'||n,'COMPLETED',clock_timestamp()from generate_series(1,2)n;
insert into internal.processed_events(event_id,school_id,source_type,source_id)select('99992500-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'10000000-0000-4000-8000-000000000001','COMPLETION',('99992400-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,2)n;
insert into app.habit_observations(school_id,id,learner_id,kind,source_type,source_object_id,occurred_at,source_event_id)select'10000000-0000-4000-8000-000000000001',('99992600-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000012','practice','ACTIVITY_COMPLETION',('99992400-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'2026-10-01T10:00:00Z',('99992500-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,2)n;
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select ok(exists(select 1 from internal.authorized_observation_sources('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',null,null)where id='99992600-0000-4000-8000-000000000001'),'Exact processed event and learner completion remains authorized');
select ok(not exists(select 1 from internal.authorized_observation_sources('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',null,null)where id='99992600-0000-4000-8000-000000000002'),'Another actor event cannot authorize this learner observation');
select ok(not exists(select 1 from internal.authorized_observation_sources('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','2026-10-01T11:00:00Z',null)where id='99992600-0000-4000-8000-000000000001'),'Selected observation window excludes earlier sources');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from internal.authorized_observation_sources('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',null,null)),0::bigint,'Parent receives no raw habit source projection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
select ok(not exists(select 1 from internal.authorized_observation_sources('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',null,null)where id='99992600-0000-4000-8000-000000000001'),'Revoked enrollment removes the exact observation source');
select ok(not has_function_privilege('cuevo_api','internal.authorized_observation_sources(uuid,uuid,timestamptz,timestamptz)','EXECUTE'),'API has no raw observation helper execution grant');
select ok(not has_function_privilege('authenticated','internal.authorized_observation_sources(uuid,uuid,timestamptz,timestamptz)','EXECUTE'),'Browser has no raw observation helper execution grant');
select ok(not has_function_privilege('cuevo_worker','internal.authorized_observation_sources(uuid,uuid,timestamptz,timestamptz)','EXECUTE'),'Worker has no raw observation helper execution grant');
select ok(not has_table_privilege('cuevo_api','app.learner_state_snapshots','SELECT'),'Raw snapshot table remains private');
select*from finish();rollback;
